SELECT CASE WHEN unit_price >= 380 THEN 'high' WHEN unit_price >= 160 THEN 'mid' ELSE 'low' END AS unit_price_bucket, ROUND(STDDEV(quantity), 2) AS stddev_quantity, SUM(unit_price) AS total_unit_price, MIN(unit_price) AS min_unit_price FROM order_items WHERE unit_price >= 380 AND quantity BETWEEN 4 AND 8 AND unit_price <= 320 GROUP BY CASE WHEN unit_price >= 380 THEN 'high' WHEN unit_price >= 160 THEN 'mid' ELSE 'low' END;
